from itertools import product

def find_magic_sequence(length, fixed_assignments):
    for seq in product(range(length + 1), repeat=length):
        if all(seq[i] == seq.count(i) for i in range(length)) and all(seq[i] == fixed_assignments.get(i, seq[i]) for i in range(length)):
            return list(seq)
    return None

fixed_assignments = {4: 0, 10: 0}
result = find_magic_sequence(11, fixed_assignments)
if result is not None:
    print(result)
else:
    print("UNSATISFIABLE")
